export async function archiveIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const archived = await issueRepo.archiveIssue(orgId, issueId);

  await emit("issue.archived", {
    ...actorEnvelope(actor),
    issueId: archived.id,
    projectId: archived.projectId,
  });

  return archived;
}

export async function bulkArchiveIssues(
  actor: Actor,
  input: BulkArchiveIssuesInput,
): Promise<{ archived: readonly IssueId[]; skipped: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const requestedIds = [...new Set(input.issueIds)];
  const matches = await issueRepo.findIssuesByIds(input.orgId, requestedIds);
  const issueById = new Map(matches.map((issue) => [issue.id, issue]));
  const toArchive: Issue[] = [];
  const skipped: IssueId[] = [];

  for (const issueId of requestedIds) {
    const issue = issueById.get(issueId);
    if (issue === undefined || issue.archivedAt !== null) {
      skipped.push(issueId);
      continue;
    }

    // Check every eligible issue before writing or publishing anything, so a
    // denied issue rejects the whole batch without partial side effects.
    assertCan(actor, "issue:archive", issueResource(issue));
    toArchive.push(issue);
  }

  const archivedIssues: Issue[] = [];
  for (const issue of toArchive) {
    archivedIssues.push(
      await issueRepo.archiveIssue(input.orgId, issue.id),
    );
  }

  for (const issue of archivedIssues) {
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: issue.id,
      projectId: issue.projectId,
    });
  }

  return {
    archived: archivedIssues.map((issue) => issue.id),
    skipped,
  };
}

